using System.Security.Cryptography; using Microsoft.Extensions.Logging; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Security; using JTradeERP.Domain.Security; using MediatR; using Microsoft.Extensions.Options;
namespace JTradeERP.Application.Features.Security.ForgotPassword;
public sealed class ForgotPasswordHandler(IApplicationDbContext db,IPasswordService passwords,IEmailSender email,IClock clock,IOptions<SecurityOptions> options,Microsoft.Extensions.Logging.ILogger<ForgotPasswordHandler> logger) : IRequestHandler<ForgotPasswordCommand,ForgotPasswordResponse>
{ public async Task<ForgotPasswordResponse> Handle(ForgotPasswordCommand r,CancellationToken ct){var generic=new ForgotPasswordResponse("If the account is eligible, password recovery instructions will be sent.");var user=db.Users.SingleOrDefault(x=>x.Email==r.Email.Trim());if(user is null||!user.IsActive)return generic;var now=clock.UtcNow;var current=db.PasswordResetOtps.Where(x=>x.UserId==user.Id&&x.InvalidatedAt==null&&x.UsedAt==null).OrderByDescending(x=>x.CreatedAt).FirstOrDefault();if(current is not null&&now<current.CreatedAt.AddSeconds(options.Value.OtpResendCooldownSeconds))return generic;if(current is not null)foreach(var otp in db.PasswordResetOtps.Where(x=>x.UserId==user.Id&&x.InvalidatedAt==null&&x.UsedAt==null).ToArray())otp.Invalidate(now);var raw=RandomNumberGenerator.GetInt32(0,1_000_000).ToString("D6");var challenge=new PasswordResetOtp(user.Id,passwords.Hash(raw),now,now.AddMinutes(options.Value.OtpMinutes));db.Add(challenge);await db.SaveChangesAsync(ct);try{await email.SendPasswordResetOtpAsync(user.Email,raw,ct);}catch(Exception){challenge.Invalidate(clock.UtcNow);await db.SaveChangesAsync(ct);logger.LogWarning("Password reset email delivery failed. CorrelationId: {CorrelationId}",System.Diagnostics.Activity.Current?.Id??"unavailable");}return generic;} }
